/* ============ Roblink UI: modals, menus, settings, actions ============ */
const A={};
const srvOf=()=>V.set&&S.servers.find(x=>x.id===V.set.sid);
function closeCtx(){$$('.ctx').forEach(e=>e.remove())}
function ctxMenu(x,y,items){closeCtx();const m=document.createElement('div');m.className='ctx';items.filter(Boolean).forEach(it=>{if(it==='-'){m.appendChild(document.createElement('hr'));return}const d=document.createElement('div');if(it.d)d.className='d';d.innerHTML=`<span>${it.l}</span>${it.r?`<span style="opacity:.6">${it.r}</span>`:''}`;d.onclick=ev=>{ev.stopPropagation();closeCtx();it.fn&&it.fn()};m.appendChild(d)});document.body.appendChild(m);const r=m.getBoundingClientRect();m.style.left=Math.max(4,Math.min(x,innerWidth-r.width-4))+'px';m.style.top=Math.max(4,Math.min(y,innerHeight-r.height-4))+'px'}
function closeModal(){const m=$('#modal');if(m){if(window._stream){window._stream.getTracks().forEach(t=>t.stop());window._stream=null}m.remove()}}
function modal(o){closeModal();const b=document.createElement('div');b.className='mback';b.id='modal';b.innerHTML=`<div class="modal ${o.wide?'wide':''}"><div class="mh2"><h2>${o.title}</h2>${o.sub?`<p>${o.sub}</p>`:''}</div><div class="mb2">${o.body||''}</div>${(o.btns||[]).length?'<div class="mf"></div>':''}</div>`;const mf=$('.mf',b);(o.btns||[]).forEach(x=>{const bt=document.createElement('button');bt.className='btn '+(x.cls||'');bt.textContent=x.label;bt.onclick=()=>{if(!x.fn||x.fn(b)!==false)closeModal()};mf.appendChild(bt)});b.addEventListener('mousedown',e=>{if(e.target===b)closeModal()});document.body.appendChild(b);if(o.onOpen)o.onOpen(b);const f=$('input:not([type=file]):not([type=checkbox]):not([type=color])',b);if(f)f.focus();return b}
const confirmBox=(title,text,label,fn,danger)=>modal({title,sub:text,btns:[{label:'Cancel',cls:'ghost'},{label,cls:danger?'danger':'primary',fn}]});
function readImage(file,max,cb,png){
  if(!file||!file.type.startsWith('image/'))return toast('Please choose an image file.','err');
  const lim=S.me.plus?100:10;if(file.size>lim*1048576)return toast(`File too large – limit is ${lim} MB${S.me.plus?'':' (Roblink Plus: 100 MB)'}.`,'err');
  const fr=new FileReader();fr.onload=()=>{if(file.type==='image/gif'){if(file.size>600*1024)return toast('GIF is too big for this demo\'s local storage (600 KB max).','err');return cb(fr.result,true)}
    const im=new Image();im.onload=()=>{const k=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);cb(c.toDataURL(png?'image/png':'image/jpeg',.85))};im.onerror=()=>toast('Could not read that image.','err');im.src=fr.result};fr.readAsDataURL(file)}
function pcard(u,s){
  const bn=(u.plus&&u.bannerImg)?`url(${u.bannerImg}) center/cover`:(u.bannerColor||u.color||'#5865f2');const m=s&&s.members[u.id];
  const roles=m?m.roles.map(id=>s.roles.find(r=>r.id===id)).filter(Boolean):[];
  return`<div class="pcard" style="${u.plus?'box-shadow:0 0 0 2px #7c5cff,0 0 24px rgba(217,70,239,.45)':''}"><div class="bn" style="background:${bn}"></div><div class="pb"><div class="pav">${av(u,80,true)}</div><h3 class="${u.plus?'plusname':''}">${esc(m&&m.nick?m.nick:u.name)} ${badges(u)}</h3><div class="pn">${esc(u.username)}${u.pronouns?' • '+esc(u.pronouns):''}</div>${u.customStatus?`<div class="pn" style="margin-top:6px">💬 ${esc(u.customStatus)}</div>`:''}<div class="sec"><h5>About me</h5>${esc(u.about||'Nothing here yet.')}</div><div class="sec"><h5>Roblink member since</h5>${new Date(u.created||now()).toLocaleDateString()}</div>${m?`<div class="sec"><h5>Roles</h5>${roles.length?roles.map(r=>`<span class="role"><i style="background:${r.color}"></i>${esc(r.name)}</span>`).join(''):'<span class="sub">No roles</span>'}</div>`:''}</div></div>`}
function showProfile(id){const u=getUser(id);if(!u)return;const s=curServer();const me=id==='me';
  const btns=[{label:'Close',cls:'ghost'}];
  if(me)btns.push({label:'Edit Profile',cls:'primary',fn:()=>{openSettings('user','account')}});
  else{btns.push({label:S.blocked.includes(id)?'Unblock':'Block',fn:()=>{A.blockToggle({dataset:{a:id}})}});if(!u.bot&&!S.friends.includes(id)&&!S.pending.some(p=>p.id===id))btns.push({label:'Add Friend',cls:'green',fn:()=>sendFriend(u.username)});btns.push({label:'Message',cls:'primary',fn:()=>openDmWith(id)})}
  modal({title:'',body:`<div style="display:flex;justify-content:center;margin-top:-20px">${pcard(u,s)}</div>`,btns})}
function openDmWith(id){let d=S.dms.find(x=>x.user===id);if(!d){d={id:uid(),user:id};S.dms.unshift(d);S.messages[d.id]=[]}go('home',null,d.id)}

/* ---------- friends ---------- */
function sendFriend(name){name=(name||'').trim().toLowerCase().replace(/^@/,'');const u=Object.values(S.users).find(x=>!x.bot&&(x.username===name||x.name.toLowerCase()===name));
  if(!u){toast('Hm, didn\'t work. Double-check that the username is correct.','err');return false}
  if(S.friends.includes(u.id)){toast(`You're already friends with ${u.name}.`);return true}
  const inc=S.pending.find(p=>p.id===u.id&&p.dir==='in');if(inc){A.acceptFr({dataset:{a:u.id}});return true}
  if(S.pending.some(p=>p.id===u.id)){toast('Request already sent.');return true}
  S.pending.push({id:u.id,dir:'out'});toast(`Friend request sent to ${u.name}!`);save();renderSide();if(!V.dm&&V.server==='home')renderMain();
  setTimeout(()=>{const i=S.pending.findIndex(p=>p.id===u.id&&p.dir==='out');if(i<0)return;S.pending.splice(i,1);S.friends.push(u.id);toast(`🎉 ${u.name} accepted your friend request!`);save();renderSide();if(!V.dm&&V.server==='home')renderMain()},3000);return true}
A.acceptFr=el=>{const id=el.dataset.a;S.pending=S.pending.filter(p=>p.id!==id);if(!S.friends.includes(id))S.friends.push(id);save();renderSide();renderMain();toast('Friend added!')};
A.declineFr=el=>{S.pending=S.pending.filter(p=>p.id!==el.dataset.a);save();renderSide();renderMain()};
A.blockToggle=el=>{const id=el.dataset.a,i=S.blocked.indexOf(id);if(i>=0)S.blocked.splice(i,1);else{S.blocked.push(id);S.friends=S.friends.filter(x=>x!==id)}save();toast(i>=0?'Unblocked.':'User blocked.');renderAll()};
A.unblock=el=>A.blockToggle(el);
A.ftab=el=>{V.ftab=el.dataset.a;renderMain()};
A.addFriend=()=>modal({title:'Add Friend',sub:'You can add friends with their Roblink username. Try <b>kira</b>, <b>mochi</b> or <b>echo</b>.',body:'<input class="input" id="fname" placeholder="Enter a username">',btns:[{label:'Cancel',cls:'ghost'},{label:'Send Friend Request',cls:'primary',fn:()=>sendFriend($('#fname').value)?true:false}]});
A.msgUser=el=>openDmWith(el.dataset.a);
A.newDm=()=>{const ids=Object.keys(S.users).filter(i=>!S.users[i].bot||true);modal({title:'Select a Friend',sub:'Start a new conversation',body:ids.map(i=>`<div class="dmrow" data-act="pickDm" data-a="${i}">${av(S.users[i],32,true)}<div class="t"><b>${esc(S.users[i].name)}${S.users[i].bot?' <span class="badge">BOT</span>':''}</b><small>${esc(S.users[i].username)}</small></div></div>`).join(''),btns:[{label:'Close',cls:'ghost'}]})};
A.pickDm=el=>{closeModal();openDmWith(el.dataset.a)};

/* ---------- navigation actions ---------- */
A.goHome=()=>go('home',null,null);A.goServer=el=>go(el.dataset.a);
A.openDm=el=>go('home',null,el.dataset.a);
A.openCh=el=>{const s=curServer(),c=s.channels.find(x=>x.id===el.dataset.a);go(s.id,c.id);if(c.type==='voice'&&!(V.voice&&V.voice.cid===c.id))A.joinVoice({dataset:{a:c.id}})};
A.toggleCat=el=>{V.collapsed[el.dataset.a]=!V.collapsed[el.dataset.a];renderSide()};
A.navToggle=()=>document.getElementById('app').classList.toggle('nav-open');
A.toggleMembers=()=>{V.members=!V.members;renderMembers()};
A.profile=el=>showProfile(el.dataset.a);
A.spoiler=el=>el.classList.toggle('open');
A.zoom=el=>{const l=document.createElement('div');l.className='lightbox';l.innerHTML=`<img src="${el.src}" alt="">`;l.onclick=()=>l.remove();document.body.appendChild(l)};
A.quick=()=>quickSwitch();
function quickSwitch(){
  const items=[];S.servers.forEach(s=>s.channels.forEach(c=>items.push({l:(c.type==='voice'?'🔊 ':'# ')+c.name,s:s.name,fn:()=>{go(s.id,c.id);if(c.type==='voice')A.joinVoice({dataset:{a:c.id}})}})));
  S.servers.forEach(s=>items.push({l:'🌐 '+s.name,s:'Server',fn:()=>go(s.id)}));Object.values(S.users).forEach(u=>items.push({l:'@ '+u.name,s:u.bot?'Bot':'User',fn:()=>openDmWith(u.id)}));
  let sel=0,list=items;const draw=b=>{$('#qlist',b).innerHTML=list.slice(0,10).map((x,i)=>`<div class="dmrow ${i===sel?'active':''}" data-qi="${i}"><div class="t"><b>${esc(x.l)}</b></div><small>${esc(x.s)}</small></div>`).join('')||'<div class="empty">No results</div>'};
  modal({title:'Where would you like to go?',body:'<input class="input" id="qin" placeholder="Search channels, servers, people…" autocomplete="off"><div id="qlist" style="margin-top:10px"></div>',onOpen:b=>{draw(b);const inp=$('#qin',b);inp.oninput=()=>{const q=inp.value.toLowerCase().replace(/^[#@]/,'');list=items.filter(x=>x.l.toLowerCase().includes(q));sel=0;draw(b)};inp.onkeydown=e=>{if(e.key==='ArrowDown'){sel=Math.min(sel+1,Math.min(list.length,10)-1);draw(b);e.preventDefault()}else if(e.key==='ArrowUp'){sel=Math.max(sel-1,0);draw(b);e.preventDefault()}else if(e.key==='Enter'&&list[sel]){closeModal();list[sel].fn()}};$('#qlist',b).onclick=e=>{const r=e.target.closest('[data-qi]');if(r){closeModal();list[+r.dataset.qi].fn()}}}})}

/* ---------- voice ---------- */
A.joinVoice=el=>{const s=curServer(),c=s.channels.find(x=>x.id===el.dataset.a);V.voice={sid:s.id,cid:c.id};if(!(s.voiceUsers[c.id]||[]).length){const ppl=Object.keys(s.members).filter(i=>i!=='me'&&!S.users[i].bot&&S.users[i].status==='online');s.voiceUsers[c.id]=ppl.sort(()=>Math.random()-.5).slice(0,rnd(1,2))}tone([[523,.1],[784,.15]]);if(V.channel!==c.id)go(s.id,c.id);else{renderSide();renderMain()}};
A.leaveVoice=()=>{V.voice=null;tone([[784,.1],[523,.15]]);renderSide();if(curChannel()&&curChannel().type==='voice')renderMain()};
A.mute=()=>{V.muted=!V.muted;if(!V.muted)V.deaf=false;renderSide();if(curChannel()&&curChannel().type==='voice')renderMain()};
A.deafen=()=>{V.deaf=!V.deaf;if(V.deaf)V.muted=true;renderSide();if(curChannel()&&curChannel().type==='voice')renderMain()};
function mediaModal(kind){modal({title:kind==='cam'?'Camera Test':'Screen Share Preview',sub:'Preview stays on your device – nothing is uploaded.',body:'<video id="vid" autoplay playsinline muted style="width:100%;border-radius:8px;background:#000;min-height:160px"></video>',btns:[{label:'Close',cls:'primary'}],onOpen:async b=>{try{const st=kind==='cam'?await navigator.mediaDevices.getUserMedia({video:true}):await navigator.mediaDevices.getDisplayMedia({video:true});window._stream=st;$('#vid',b).srcObject=st}catch(e){toast(kind==='cam'?'Could not access a camera (permission denied or none found).':'Screen sharing was cancelled or is not supported.','err')}}})}
A.camTest=()=>mediaModal('cam');A.shareScreen=()=>mediaModal('screen');
A.soundboard=()=>{const p=S.me.plus;modal({title:'🔊 Soundboard',sub:p?'Click a sound to play it.':'Soundboard is a <b>Roblink Plus</b> perk.',body:`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">${Object.keys(SOUNDS).map(k=>`<button class="btn" data-act="playSound" data-a="${k}" ${p?'':'disabled'}>🔈 ${k}</button>`).join('')}</div>`,btns:[{label:'Close',cls:'ghost'},p?null:{label:'Get Plus',cls:'primary',fn:()=>openSettings('user','plus')}].filter(Boolean)})};
A.playSound=el=>tone(SOUNDS[el.dataset.a],1);

/* ---------- status ---------- */
A.statusMenu=el=>{const r=el.getBoundingClientRect(),set=s=>()=>{S.me.status=s;save();renderSide();renderMembers();renderMsgs()};ctxMenu(r.left,r.top-220,[{l:'🟢 Online',fn:set('online')},{l:'🌙 Idle',fn:set('idle')},{l:'⛔ Do Not Disturb',fn:set('dnd')},{l:'⚫ Invisible',fn:set('invisible')},'-',{l:'💬 Set Custom Status',fn:()=>modal({title:'Set a custom status',body:`<input class="input" id="cs" maxlength="60" value="${esc(S.me.customStatus||'')}" placeholder="What's happening?">`,btns:[{label:'Cancel',cls:'ghost'},{label:'Save',cls:'primary',fn:()=>{S.me.customStatus=$('#cs').value.trim();save();renderSide();renderMembers()}}]})},S.me.customStatus?{l:'Clear Status',fn:()=>{S.me.customStatus='';save();renderSide()}}:null])};

/* ---------- server create / join / explore ---------- */
A.addServer=()=>{let tpl='gaming';modal({title:'Create Your Server',sub:'Your server is where you and your friends hang out.',body:`<div class="tpls" id="tpls">${Object.entries(TPL).map(([k,t])=>`<div class="tpl ${k===tpl?'on':''}" data-tpl="${k}">${t.n}</div>`).join('')}</div><label class="lbl">Server name</label><input class="input" id="sname" maxlength="40" value="${esc(S.me.name)}'s server"><div class="row" style="border:0"><div><b style="color:var(--text)">Add starter bots</b><p class="sub">DiceBot &amp; ModBot</p></div><label class="toggle"><input type="checkbox" id="sbots" checked><i></i></label></div><div class="sub" style="text-align:center">Have an invite already? <a href="#" data-act="joinServer">Join a server</a></div>`,btns:[{label:'Cancel',cls:'ghost'},{label:'Create',cls:'primary',fn:()=>{const n=$('#sname').value.trim();if(!n){toast('Give your server a name.','err');return false}const s=mkServer({name:n,color:pick(COLORS),owner:'me',tpl,bots:$('#sbots').checked?['modbot','dicebot']:[]});S.servers.push(s);audit(s,'created the server');const g=s.channels.find(c=>c.type==='text'&&c.name==='general')||s.channels[0];if(s.bots.includes('modbot'))S.messages[g.id].push({id:uid(),a:'modbot',t:`👋 Welcome to **${esc(n)}**! Open ⚙️ Server Settings from the server name to add roles, bots and emoji.`,ts:now(),rx:{}});go(s.id,g.id);toast('Server created!')}}],onOpen:b=>{$('#tpls',b).onclick=e=>{const t=e.target.closest('[data-tpl]');if(!t)return;tpl=t.dataset.tpl;$$('.tpl',b).forEach(x=>x.classList.toggle('on',x===t))}}})};
function joinByCode(code){code=(code||'').trim().toLowerCase().replace(/^.*\//,'');if(!code)return toast('Enter an invite code.','err');
  const mine=S.servers.find(s=>s.invite===code||s.invites.some(i=>i.code===code));if(mine){go(mine.id);toast('You\'re already in that server.');return true}
  const i=S.directory.findIndex(s=>s.invite===code||s.invites.some(x=>x.code===code));if(i<0){toast('Invite is invalid or has expired.','err');return false}
  const s=S.directory.splice(i,1)[0];if(s.bans.some(b=>b.id==='me')){S.directory.push(s);toast('You are banned from this server.','err');return false}
  s.members.me={roles:[],nick:'',joined:now(),timeout:0};S.servers.push(s);const g=s.channels.find(c=>c.name==='general')||s.channels.find(c=>c.type==='text');S.messages[g.id].push({id:uid(),a:'sys',sys:1,t:`**${esc(S.me.name)}** just joined the server. Say hi! 👋`,ts:now(),rx:{}});go(s.id,g.id);toast(`Joined ${s.name}!`);return true}
A.joinServer=()=>{closeModal();modal({title:'Join a Server',sub:'Enter an invite below to join an existing server.',body:'<label class="lbl">Invite code *</label><input class="input" id="jcode" placeholder="e.g. script"><div class="sub" style="margin-top:8px">Demo invites: <b>script</b>, <b>chill</b>, <b>race</b></div>',btns:[{label:'Cancel',cls:'ghost'},{label:'Join Server',cls:'primary',fn:()=>joinByCode($('#jcode').value)?true:false}]})};
A.explore=()=>modal({title:'🧭 Explore Servers',sub:'Discover public communities.',wide:1,body:S.directory.length?S.directory.map(s=>`<div class="card" style="display:flex;gap:12px;align-items:center"><div class="srv" style="background:${s.color};flex:none">${esc(s.icon)}</div><div style="flex:1"><b style="color:var(--text)">${esc(s.name)}</b><div class="sub">${esc(s.desc)} • ${Object.keys(s.members).length} members</div></div><button class="btn primary sm" data-act="joinDir" data-a="${s.invite}">Join</button></div>`).join(''):'<div class="empty">You\'ve joined every public server! 🎉</div>',btns:[{label:'Have an invite code?',fn:()=>{setTimeout(A.joinServer,0)}},{label:'Close',cls:'ghost'}]});
A.joinDir=el=>{closeModal();joinByCode(el.dataset.a)};

/* ---------- server menu / invite ---------- */
A.serverMenu=el=>{const s=curServer(),r=el.getBoundingClientRect(),can=p=>perm(s,'me',p);
  ctxMenu(r.left+8,r.bottom+4,[{l:'👥 Invite People',fn:()=>inviteModal(s)},anyManage(s)?{l:'⚙️ Server Settings',fn:()=>openSettings('server',null,s.id)}:null,can('MANAGE_CHANNELS')?{l:'➕ Create Channel',fn:()=>A.newCh({dataset:{a:s.categories[0]&&s.categories[0].id}})}:null,can('MANAGE_CHANNELS')?{l:'📁 Create Category',fn:()=>newCatModal(s)}:null,{l:'🚀 Boost Server',fn:()=>openSettings('server','boost',s.id)},{l:'✏️ Edit Server Nickname',fn:()=>nickModal(s)},'-',s.owner==='me'?{l:'🗑️ Delete Server',d:1,fn:()=>openSettings('server','delete',s.id)}:{l:'🚪 Leave Server',d:1,fn:()=>leaveServer(s)}])};
function nickModal(s){modal({title:'Change Nickname',sub:`Only in ${esc(s.name)}`,body:`<input class="input" id="nk" maxlength="32" value="${esc(s.members.me.nick||'')}" placeholder="${esc(S.me.name)}">`,btns:[{label:'Cancel',cls:'ghost'},{label:'Save',cls:'primary',fn:()=>{s.members.me.nick=$('#nk').value.trim();save();refreshApp()}}]})}
function newCatModal(s){modal({title:'Create Category',body:'<input class="input" id="cn" maxlength="30" placeholder="New Category">',btns:[{label:'Cancel',cls:'ghost'},{label:'Create',cls:'primary',fn:()=>{const n=$('#cn').value.trim();if(!n)return false;s.categories.push({id:uid(),name:n});audit(s,`created category ${n}`);save();renderSide();if(V.set)renderSet()}}]})}
function leaveServer(s){if(s.owner==='me')return toast('Transfer ownership or delete the server instead.','err');confirmBox('Leave Server',`Are you sure you want to leave <b>${esc(s.name)}</b>?`,'Leave Server',()=>{delete s.members.me;S.servers=S.servers.filter(x=>x!==s);S.directory.push(s);if(V.voice&&V.voice.sid===s.id)V.voice=null;go('home')},1)}
function inviteModal(s){
  if(!perm(s,'me','INVITE'))return toast('You do not have permission to create invites.','err');
  modal({title:`Invite friends to ${esc(s.name)}`,body:`<label class="lbl">Invite code</label><div style="display:flex;gap:8px"><input class="input" readonly value="${s.invite}"><button class="btn primary" data-act="copy" data-a="${s.invite}">Copy</button></div><label class="lbl">Send to a friend</label>${S.friends.map(i=>`<div class="frow">${av(S.users[i],32,true)}<div class="t"><b>${esc(S.users[i].name)}</b></div><button class="btn sm" data-act="sendInvite" data-a="${i}" data-b="${s.id}">Invite</button></div>`).join('')||'<div class="empty">Add some friends first!</div>'}`,btns:[{label:'Done',cls:'primary'}]})}
A.copy=el=>{navigator.clipboard&&navigator.clipboard.writeText(el.dataset.a).then(()=>toast('Copied!'),()=>toast('Copy failed','err'))};
A.sendInvite=el=>{const s=S.servers.find(x=>x.id===el.dataset.b),u=S.users[el.dataset.a];let d=S.dms.find(x=>x.user===u.id);if(!d){d={id:uid(),user:u.id};S.dms.unshift(d);S.messages[d.id]=[]}S.messages[d.id].push({id:uid(),a:'me',t:`Join me in **${esc(s.name)}**! Invite code: \`${s.invite}\``,ts:now(),rx:{}});el.textContent='Sent ✓';el.disabled=true;save();renderSide();setTimeout(()=>npcDm(u.id,d.id,'thanks!'),300)};

/* ---------- channels ---------- */
const actSrv=()=>(V.set&&V.set.kind==='server'?srvOf():curServer());
A.newCh=el=>{const s=actSrv();let type='text';modal({title:'Create Channel',body:`<label class="lbl">Channel type</label><div class="tpls" id="ctype"><div class="tpl on" data-t="text"># Text</div><div class="tpl" data-t="voice">🔊 Voice</div></div><label class="lbl">Channel name</label><input class="input" id="chn" maxlength="30" placeholder="new-channel"><label class="lbl">Category</label><select class="input" id="chc"><option value="">None</option>${s.categories.map(k=>`<option value="${k.id}" ${k.id===el.dataset.a?'selected':''}>${esc(k.name)}</option>`).join('')}</select>`,btns:[{label:'Cancel',cls:'ghost'},{label:'Create Channel',cls:'primary',fn:()=>{let n=$('#chn').value.trim();if(!n)return false;if(type==='text')n=n.toLowerCase().replace(/\s+/g,'-').replace(/[^a-z0-9\-_]/g,'');const c={id:uid(),name:n,type,cat:$('#chc').value||null,topic:''};s.channels.push(c);S.messages[c.id]=[];if(type==='voice')s.voiceUsers[c.id]=[];audit(s,`created channel ${n}`);go(s.id,c.id);if(V.set)renderSet()}}],onOpen:b=>{$('#ctype',b).onclick=e=>{const t=e.target.closest('[data-t]');if(!t)return;type=t.dataset.t;$$('.tpl',b).forEach(x=>x.classList.toggle('on',x===t))}}})};
A.editCh=(el,e)=>{if(e)e.stopPropagation();const s=actSrv(),c=s.channels.find(x=>x.id===el.dataset.a);if(!perm(s,'me','MANAGE_CHANNELS'))return;
  modal({title:'Edit Channel',body:`<label class="lbl">Channel name</label><input class="input" id="chn" maxlength="30" value="${esc(c.name)}">${c.type==='text'?`<label class="lbl">Topic</label><input class="input" id="cht" maxlength="120" value="${esc(c.topic||'')}">`:''}`,btns:[{label:'Delete',cls:'danger',fn:()=>{setTimeout(()=>delChannel(s,c),0)}},{label:'Cancel',cls:'ghost'},{label:'Save',cls:'primary',fn:()=>{const n=$('#chn').value.trim();if(!n)return false;c.name=c.type==='text'?n.toLowerCase().replace(/\s+/g,'-'):n;if($('#cht'))c.topic=$('#cht').value.trim();audit(s,`edited channel ${c.name}`);save();refreshApp();if(V.set)renderSet()}}]})};
function delChannel(s,c){if(s.channels.filter(x=>x.type==='text').length<2&&c.type==='text')return toast('A server needs at least one text channel.','err');confirmBox('Delete Channel',`Delete <b>${esc(c.name)}</b>? This cannot be undone.`,'Delete Channel',()=>{s.channels=s.channels.filter(x=>x!==c);delete S.messages[c.id];audit(s,`deleted channel ${c.name}`);if(V.channel===c.id)go(s.id);else{renderSide();save()}if(V.set)renderSet()},1)}

/* ---------- messages: actions ---------- */
const findMsg=id=>(S.messages[convKey()]||[]).find(m=>m.id===id);
function toggleReact(mid,emo){const m=findMsg(mid),s=curServer();if(!m)return;if(s&&!perm(s,'me','REACT'))return toast('You can\'t add reactions here.','err');
  if(emo[0]===':'&&!S.me.plus&&!(s&&s.emojis.some(e=>':'+e.name+':'===emo)))return toast('Using emoji from other servers requires Roblink Plus 💎','err');
  const l=m.rx[emo]=m.rx[emo]||[],i=l.indexOf('me');if(i>=0)l.splice(i,1);else l.push('me');renderMsgs();save()}
A.react=el=>toggleReact(el.dataset.a,el.dataset.b);
A.reply=el=>{V.reply=el.dataset.a;renderReply();$('#input')&&$('#input').focus()};
A.cancelReply=()=>{V.reply=null;renderReply()};
A.edit=el=>{V.edit=el.dataset.a;renderMsgs()};
A.cancelEdit=()=>{V.edit=null;renderMsgs()};
A.saveEdit=()=>{const b=$('#editbox');if(!b)return;const m=findMsg(V.edit),v=b.value.trim();V.edit=null;if(m&&v&&v!==m.t){m.t=v;m.ed=now()}renderMsgs();save()};
A.pin=el=>{const m=findMsg(el.dataset.a);if(!m)return;m.pin=!m.pin;const s=curServer();if(s)audit(s,(m.pin?'pinned':'unpinned')+' a message');renderMsgs();save();toast(m.pin?'Message pinned.':'Message unpinned.')};
A.del=el=>{const l=S.messages[convKey()],i=l.findIndex(m=>m.id===el.dataset.a);if(i>=0){l.splice(i,1);renderMsgs();save()}};
A.vote=el=>{const m=findMsg(el.dataset.a),i=+el.dataset.b,had=m.poll.options[i].v.includes('me');m.poll.options.forEach(o=>o.v=o.v.filter(x=>x!=='me'));if(!had)m.poll.options[i].v.push('me');
  if(!had)m.poll.options.forEach(o=>{if(Math.random()<.3)o.v.push(pick(NPCS)[0])});renderMsgs();save()};
A.jumpMsg=el=>{const t=$(`.msg[data-id="${el.dataset.a}"]`);if(t){t.scrollIntoView({block:'center'});t.classList.add('hl');setTimeout(()=>t.classList.remove('hl'),2000)}};
A.rmAtt=()=>{V.att=null;renderAtt()};
A.superReact=el=>{const m=findMsg(el.dataset.a);if(!m)return;const e=pick(['💥','🔥','✨','🎉','💎','⚡']);(m.rx[e]=m.rx[e]||[]).includes('me')||m.rx[e].push('me');renderMsgs();save();const r=$(`.msg[data-id="${m.id}"]`);const b=r?r.getBoundingClientRect():{left:innerWidth/2,top:innerHeight/2};for(let i=0;i<16;i++){const p=document.createElement('div');p.className='burst';p.textContent=e;p.style.cssText=`left:${b.left+120}px;top:${b.top+20}px;--dx:${rnd(-220,220)}px;--dy:${rnd(-200,60)}px;--r:${rnd(-90,90)}deg`;document.body.appendChild(p);setTimeout(()=>p.remove(),1250)}tone([[660,.08],[880,.08],[1320,.18]])};
A.send=()=>{const i=$('#input');if(!i)return;if(sendMsg(i.value,V.att)){i.value='';V.drafts[convKey()]='';V.att=null;autosize(i);renderAtt();$('#suggest').style.display='none';$('#cnt').textContent=''}};
function autosize(t){if(!t)return;t.style.height='44px';t.style.height=Math.min(t.scrollHeight,300)+'px'}
A.pins=()=>{const l=(S.messages[convKey()]||[]).filter(m=>m.pin);modal({title:'📌 Pinned Messages',wide:1,body:l.length?l.map(m=>{const u=getUser(m.a);return`<div class="card"><div style="display:flex;gap:10px;align-items:center">${av(u,28)}<b style="color:var(--text)">${esc(u.name)}</b><span class="ts">${fmtTime(m.ts)}</span><span style="flex:1"></span><button class="btn sm" data-act="pinJump" data-a="${m.id}">Jump</button></div><div style="margin-top:6px">${fmt(m.t||'')}</div></div>`}).join(''):'<div class="empty">No pinned messages here yet.<br>Hover a message and press 📌.</div>',btns:[{label:'Close',cls:'primary'}]})};
A.pinJump=el=>{closeModal();jumpTo(V.server,V.channel,el.dataset.a,V.dm)};
function doSearch(q){q=q.trim().toLowerCase();if(!q)return;const s=curServer(),res=[];const chans=s?s.channels.filter(c=>c.type==='text'):[{id:V.dm,name:'dm'}];chans.forEach(c=>(S.messages[c.id]||[]).forEach(m=>{if(!m.sys&&m.t&&m.t.toLowerCase().includes(q))res.push([c,m])}));
  modal({title:`Search: “${esc(q)}”`,sub:`${res.length} result${res.length===1?'':'s'}`,wide:1,body:res.slice(-30).reverse().map(([c,m])=>{const u=getUser(m.a)||{name:'?'};return`<div class="card" style="cursor:pointer" data-act="srJump" data-a="${m.id}" data-b="${c.id}"><div class="sub">${s?'#'+esc(c.name)+' • ':''}<b style="color:var(--text)">${esc(u.name)}</b> • ${fmtTime(m.ts)}</div><div>${esc(m.t.slice(0,200))}</div></div>`}).join('')||'<div class="empty">No messages found.</div>',btns:[{label:'Close',cls:'primary'}]})}
A.srJump=el=>{closeModal();jumpTo(V.server,V.dm?null:el.dataset.b,el.dataset.a,V.dm)};

/* ---------- emoji picker ---------- */
function emojiPicker(target,anchor){
  $('.picker')&&$('.picker').remove();let tab='Smileys',q='';const p=document.createElement('div');p.className='picker fixed';
  const customs=()=>{const s=curServer(),own=s?s.emojis:[],other=S.servers.filter(x=>x!==s).flatMap(x=>x.emojis.map(e=>({...e,from:x.name})));return{own,other}};
  const grid=()=>{let h='';const c=customs();const match=n=>!q||n.toLowerCase().includes(q);
    if(tab==='Custom'||q){const o=c.own.filter(e=>match(e.name));if(o.length)h+=`<div class="gl">${curServer()?esc(curServer().name):'Custom'}</div>`+o.map(e=>`<button data-e=":${e.name}:" title=":${e.name}:"><img src="${e.data}" alt=""></button>`).join('');
      const ot=c.other.filter(e=>match(e.name));if(ot.length)h+=`<div class="gl">Other servers ${S.me.plus?'':'🔒 Plus'}</div>`+ot.map(e=>`<button data-e=":${e.name}:" title=":${e.name}:" style="${S.me.plus?'':'opacity:.45'}"><img src="${e.data}" alt=""></button>`).join('')}
    if(tab!=='Custom'||q)Object.entries(EMO).forEach(([k,l])=>{if(q||tab===k){const f=l.filter(x=>!q);if(!q)h+=l.map(x=>`<button data-e="${x}">${x}</button>`).join('')}});
    if(q&&!h)h='<div class="empty" style="width:100%">No emoji found</div>';p.querySelector('.grid').innerHTML=h};
  p.innerHTML=`<input class="input" placeholder="Search emoji" id="eq"><div class="tabs">${['Custom','Smileys','Gestures','Things'].map(t=>`<button data-t="${t}" class="${t===tab?'on':''}">${{Custom:'⭐',Smileys:'😀',Gestures:'👍',Things:'🎮'}[t]}</button>`).join('')}</div><div class="grid"></div>`;
  document.body.appendChild(p);const r=anchor.getBoundingClientRect();p.style.left=Math.max(8,Math.min(r.right-340,innerWidth-348))+'px';p.style.top=Math.max(8,Math.min(r.top-366,innerHeight-370))+'px';if(r.top<380)p.style.top=Math.min(r.bottom+6,innerHeight-370)+'px';
  grid();$('#eq',p).oninput=e=>{q=e.target.value.toLowerCase();grid()};
  p.querySelector('.tabs').onclick=e=>{const b=e.target.closest('[data-t]');if(!b)return;tab=b.dataset.t;$$('.tabs button',p).forEach(x=>x.classList.toggle('on',x===b));$('#eq',p).value='';q='';grid()};
  p.querySelector('.grid').onclick=e=>{const b=e.target.closest('[data-e]');if(!b)return;const em=b.dataset.e;
    if(em[0]===':'){const own=curServer()&&curServer().emojis.some(x=>':'+x.name+':'===em);if(!own&&!S.me.plus)return toast('Custom emoji from other servers need Roblink Plus 💎','err')}
    if(target==='composer'){const i=$('#input');if(i){const a=i.selectionStart,z=i.selectionEnd;i.value=i.value.slice(0,a)+em+i.value.slice(z);i.focus();i.selectionStart=i.selectionEnd=a+em.length;i.dispatchEvent(new Event('input'))}}else toggleReact(target,em);p.remove()}}
A.emojiPick=(el)=>emojiPicker('composer',el);A.reactPick=el=>emojiPicker(el.dataset.a,el);

/* ---------- context menus ---------- */
function ctxFor(el,x,y){
  const t=el.dataset.ctx,s=curServer(),dev=S.set.dev,cp=(l,v)=>dev?{l:'🆔 Copy '+l+' ID',fn:()=>A.copy({dataset:{a:v}})}:null;
  if(t==='msg'){const m=findMsg(el.dataset.id);if(!m)return;const mine=m.a==='me',canDel=mine||(s&&perm(s,'me','MANAGE_MESSAGES'));ctxMenu(x,y,[{l:'↩️ Reply',fn:()=>A.reply({dataset:{a:m.id}})},{l:'😀 Add Reaction',fn:()=>emojiPicker(m.id,el)},mine?{l:'✏️ Edit Message',fn:()=>A.edit({dataset:{a:m.id}})}:null,{l:'📋 Copy Text',fn:()=>A.copy({dataset:{a:m.t||''}})},(!s||perm(s,'me','MANAGE_MESSAGES'))?{l:m.pin?'📌 Unpin Message':'📌 Pin Message',fn:()=>A.pin({dataset:{a:m.id}})}:null,cp('Message',m.id),canDel?'-':null,canDel?{l:'🗑️ Delete Message',d:1,fn:()=>A.del({dataset:{a:m.id}})}:null])}
  else if(t==='member'){const id=el.dataset.a;if(!id)return;const u=getUser(id);if(!u)return;const items=[{l:'👤 Profile',fn:()=>showProfile(id)}];
    if(id!=='me')items.push({l:'💬 Message',fn:()=>openDmWith(id)});
    if(s&&s.members[id]&&id!=='me'&&canManage(s,id)){items.push('-');if(perm(s,'me','TIMEOUT'))items.push({l:'⏳ Timeout',fn:()=>timeoutModal(s,id)});if(perm(s,'me','KICK'))items.push({l:'👢 Kick '+esc(u.name),d:1,fn:()=>modAct('kick',s,id)});if(perm(s,'me','BAN'))items.push({l:'🔨 Ban '+esc(u.name),d:1,fn:()=>modAct('ban',s,id)})}
    if(id!=='me'&&!u.bot){items.push('-');if(S.friends.includes(id))items.push({l:'Remove Friend',d:1,fn:()=>{S.friends=S.friends.filter(x=>x!==id);save();renderAll()}});items.push({l:S.blocked.includes(id)?'Unblock':'Block',d:1,fn:()=>A.blockToggle({dataset:{a:id}})})}
    items.push(cp('User',id));ctxMenu(x,y,items)}
  else if(t==='channel'){const sv=curServer(),c=sv.channels.find(k=>k.id===el.dataset.a);ctxMenu(x,y,[{l:'✅ Mark as Read',fn:()=>{clearUnread(c.id);renderRail();renderSide()}},perm(sv,'me','MANAGE_CHANNELS')?{l:'⚙️ Edit Channel',fn:()=>A.editCh({dataset:{a:c.id}})}:null,perm(sv,'me','MANAGE_CHANNELS')?{l:'🗑️ Delete Channel',d:1,fn:()=>delChannel(sv,c)}:null,cp('Channel',c.id)])}
  else if(t==='server'){const sv=S.servers.find(k=>k.id===el.dataset.a);ctxMenu(x,y,[{l:'✅ Mark as Read',fn:()=>{sv.channels.forEach(c=>clearUnread(c.id));renderRail();renderSide()}},{l:'👥 Invite People',fn:()=>inviteModal(sv)},anyManage(sv)?{l:'⚙️ Server Settings',fn:()=>openSettings('server',null,sv.id)}:null,'-',sv.owner==='me'?{l:'🗑️ Delete Server',d:1,fn:()=>openSettings('server','delete',sv.id)}:{l:'🚪 Leave Server',d:1,fn:()=>leaveServer(sv)},cp('Server',sv.id)])}
  else if(t==='dm'){const d=S.dms.find(k=>k.id===el.dataset.a);ctxMenu(x,y,[{l:'👤 Profile',fn:()=>showProfile(d.user)},{l:'✖ Close DM',fn:()=>{S.dms=S.dms.filter(k=>k!==d);if(V.dm===d.id)go('home');else{renderSide();save()}}},cp('User',d.user)])}}

/* ---------- moderation ---------- */
function timeoutModal(s,id){modal({title:`Timeout ${esc(getUser(id).name)}`,sub:'They won\'t be able to send messages or react.',body:'<select class="input" id="tod"><option value="60">60 seconds</option><option value="300">5 minutes</option><option value="3600">1 hour</option><option value="86400">1 day</option><option value="0">Remove timeout</option></select>',btns:[{label:'Cancel',cls:'ghost'},{label:'Apply',cls:'primary',fn:()=>{const sec=+$('#tod').value;s.members[id].timeout=sec?now()+sec*1000:0;audit(s,sec?`timed out ${getUser(id).name}`:`removed timeout from ${getUser(id).name}`);save();toast(sec?'Timeout applied.':'Timeout removed.');if(V.set)renderSet()}}]})}
function modAct(kind,s,id){const u=getUser(id);if(!canManage(s,id))return toast('You can\'t manage someone with an equal or higher role.','err');
  modal({title:(kind==='ban'?'Ban ':'Kick ')+esc(u.name),sub:kind==='ban'?'They will not be able to rejoin unless unbanned.':'They can rejoin with an invite.',body:'<label class="lbl">Reason (optional)</label><input class="input" id="rsn" maxlength="100">',btns:[{label:'Cancel',cls:'ghost'},{label:kind==='ban'?'Ban':'Kick',cls:'danger',fn:()=>{const r=$('#rsn').value.trim();delete s.members[id];s.bots=s.bots.filter(b=>b!==id);if(kind==='ban')s.bans.push({id,reason:r,ts:now()});audit(s,`${kind==='ban'?'banned':'kicked'} ${u.name}${r?' ('+r+')':''}`);const g=s.channels.find(c=>c.name==='general')||s.channels.find(c=>c.type==='text');S.messages[g.id].push({id:uid(),a:'sys',sys:1,t:`**${esc(u.name)}** was ${kind==='ban'?'banned':'kicked'}.`,ts:now(),rx:{}});s.voiceUsers&&Object.keys(s.voiceUsers).forEach(k=>s.voiceUsers[k]=s.voiceUsers[k].filter(x=>x!==id));save();refreshApp();if(V.set)renderSet();toast(`${u.name} was ${kind==='ban'?'banned':'kicked'}.`)}}]})}

/* ============ SETTINGS ============ */
const tog=(path,label,desc,val,dis,plus)=>`<div class="row"><div><b style="color:var(--text)">${label}</b>${plus?' <span class="badge plus">PLUS</span>':''}${desc?`<p class="sub">${desc}</p>`:''}</div><label class="toggle"><input type="checkbox" data-bind="${path}" ${plus?'data-plus="1"':''} ${val?'checked':''} ${dis?'disabled':''}><i></i></label></div>`;
const fld=(label,path,val,o={})=>`<label class="lbl">${label}</label>${o.area?`<textarea class="input" rows="3" data-bind="${path}" maxlength="${o.max||200}" ${o.dis?'disabled':''}>${esc(val)}</textarea>`:`<input class="input" data-bind="${path}" value="${esc(val)}" maxlength="${o.max||40}" ${o.dis?'disabled':''}>`}`;
const selb=(label,path,val,opts,dis)=>`<label class="lbl">${label}</label><select class="input" data-bind="${path}" ${dis?'disabled':''}>${opts.map(([v,l])=>`<option value="${v}" ${String(v)===String(val)?'selected':''}>${l}</option>`).join('')}</select>`;
const swatches=(path,val,dis)=>`<div class="swatches">${COLORS.map(c=>`<div class="sw ${c===val?'on':''}" style="background:${c}" data-act="${dis?'noop':'setColor'}" data-a="${path}" data-b="${c}">${c===val?'✓':''}</div>`).join('')}</div>`;
const lock=(s,perm_)=>`<div class="card" style="border-left:4px solid var(--yellow)">🔒 You need the <b>${PERMS[perm_]?PERMS[perm_][0]:perm_}</b> permission to change this. You can view it but not edit.</div>`;
function openSettings(kind,sec,sid){closeModal();V.set={kind,sec:sec||(kind==='user'?'account':'overview'),sid:sid||V.server,role:null,q:''};if(kind==='server'){const s=srvOf();if(!s||!anyManage(s)){V.set=null;return toast('You don\'t have permission to open server settings.','err')}}renderSet()}
A.openSet=el=>openSettings('user',el.dataset.a);
A.closeSet=()=>{V.set=null;const e=$('#settings');if(e)e.remove()};
A.setSec=el=>{V.set.sec=el.dataset.a;renderSet();$('.scw').scrollTop=0};
A.noop=()=>{};
function resolvePath(path){const p=path.split('.');const root=p.shift();const o=root==='me'?S.me:root==='set'?S.set:root==='srv'?srvOf():null;return{o,p}}
function setPath(path,val){const{o,p}=resolvePath(path);let t=o;for(let i=0;i<p.length-1;i++)t=t[p[i]];t[p[p.length-1]]=val}
A.setColor=el=>{setPath(el.dataset.a,el.dataset.b);save();applyTheme();refreshApp();renderSet()};
const USEC=[['account','My Account'],['privacy','Privacy & Safety'],['plus','💎 Roblink Plus'],['--','App Settings'],['appearance','Appearance'],['notifs','Notifications'],['voice','Voice & Video'],['keybinds','Keybinds'],['advanced','Advanced']];
const SSEC=[['overview','Overview','MANAGE_SERVER'],['roles','Roles','MANAGE_ROLES'],['emoji','Emoji','MANAGE_EMOJI'],['boost','Boost Status'],['safety','Safety Setup','MANAGE_SERVER'],['--','User Management'],['channels','Channels','MANAGE_CHANNELS'],['members','Members'],['bots','Bots & Integrations','MANAGE_SERVER'],['invites','Invites'],['bans','Bans','BAN'],['audit','Audit Log'],['--',''],['delete','Delete / Leave Server']];
function renderSet(){
  const st=V.set;if(!st)return;let el=$('#settings');if(!el){el=document.createElement('div');el.id='settings';document.body.appendChild(el)}
  const sc=$('.scw',el),top=sc?sc.scrollTop:0,s=st.kind==='server'?srvOf():null;let nav='',body='';
  if(st.kind==='user'){nav=`<h6>User Settings</h6>`+USEC.map(([k,l])=>k==='--'?`<h6>${l}</h6>`:`<div class="it ${st.sec===k?'on':''}" data-act="setSec" data-a="${k}">${l}</div>`).join('')+`<hr style="border:0;border-top:1px solid var(--line);margin:10px 0"><div class="it d" data-act="logout">Log Out / Reset</div>`;body=({account:secAccount,privacy:secPrivacy,plus:secPlus,appearance:secAppearance,notifs:secNotifs,voice:secVoice,keybinds:secKeys,advanced:secAdvanced}[st.sec]||secAccount)()}
  else{nav=`<h6>${esc(s.name)}</h6>`+SSEC.map(([k,l])=>k==='--'?(l?`<h6>${l}</h6>`:'<hr style="border:0;border-top:1px solid var(--line);margin:10px 0">'):`<div class="it ${st.sec===k?'on':''}" data-act="setSec" data-a="${k}">${l}</div>`).join('');body=({overview:secOverview,roles:secRoles,emoji:secEmoji,boost:secBoost,safety:secSafety,channels:secChannels,members:secMembers,bots:secBots,invites:secInvites,bans:secBans,audit:secAudit,delete:secDelete}[st.sec]||secOverview)(s)}
  el.innerHTML=`<div class="snavw"><div class="snav">${nav}</div></div><div class="scw"><button class="sclose" data-act="closeSet" title="Close (Esc)">✕</button><div class="scontent">${body}</div></div>`;$('.scw',el).scrollTop=top}
function updatePreview(){const p=$('#prevcard');if(p)p.innerHTML=pcard(S.me,null)}
A.logout=()=>confirmBox('Log out & reset?','This clears all Roblink data stored in this browser (servers, messages, settings) and returns you to sign-up.','Log Out',()=>{localStorage.removeItem(KEY);location.reload()},1);

function secAccount(){const m=S.me;return`<h2>My Account</h2><div id="prevcard">${pcard(m,null)}</div>
  ${fld('Display name','me.name',m.name,{max:32})}${fld('Username','me.username',m.username,{max:20})}${fld('Pronouns','me.pronouns',m.pronouns||'',{max:20})}${fld('About me','me.about',m.about||'',{area:1,max:190})}${fld('Custom status','me.customStatus',m.customStatus||'',{max:60})}
  ${selb('Status','me.status',m.status,[['online','🟢 Online'],['idle','🌙 Idle'],['dnd','⛔ Do Not Disturb'],['invisible','⚫ Invisible']])}
  <h3>Avatar</h3><div class="swatches" style="margin-bottom:10px">${COLORS.map(c=>`<div class="sw ${c===m.color?'on':''}" style="background:${c}" data-act="setColor" data-a="me.color" data-b="${c}">${c===m.color?'✓':''}</div>`).join('')}</div>
  <label class="btn primary">Upload avatar<input type="file" id="avFile" accept="image/*" hidden></label> <button class="btn" data-act="rmAvatar">Remove</button><p class="sub">${m.plus?'💎 Animated GIF avatars unlocked.':'GIF avatars require Roblink Plus 💎'}</p>
  <h3>Profile banner</h3><div class="swatches"><input type="color" data-bind="me.bannerColor" value="${m.bannerColor||'#5865f2'}" style="width:48px;height:32px;border:0;background:none"></div><br><label class="btn ${m.plus?'primary':''}">Upload banner image 💎<input type="file" id="bnFile" accept="image/*" hidden></label> <button class="btn" data-act="rmBanner">Remove image</button><p class="sub">${m.plus?'':'Banner images require Roblink Plus.'}</p>`}
A.rmAvatar=()=>{S.me.avatarImg=null;save();updatePreview();refreshApp();renderSet()};A.rmBanner=()=>{S.me.bannerImg=null;save();updatePreview();renderSet()};
function secPrivacy(){const s=S.set;return`<h2>Privacy &amp; Safety</h2>${tog('set.dmMembers','Allow DMs from server members','Members of servers you\'re in can message you.',s.dmMembers)}${selb('Who can send you friend requests','set.friendReq',s.friendReq,[['all','Everyone'],['mutual','Friends of friends'],['none','No one']])}${selb('Filter explicit media in DMs','set.explicit',s.explicit,[['off','Don\'t scan any messages'],['friends','Scan from non-friends'],['all','Scan everything']])}${tog('set.hideTyping','Hide my typing indicator','',s.hideTyping)}
  <h3>Blocked users</h3>${S.blocked.length?S.blocked.map(i=>`<div class="frow">${av(S.users[i],32)}<div class="t"><b>${esc(S.users[i].name)}</b></div><button class="btn sm" data-act="unblock" data-a="${i}">Unblock</button></div>`).join(''):'<p class="sub">No blocked users.</p>'}
  <h3>Your data</h3><button class="btn" data-act="exportData">⬇️ Export my data (JSON)</button> <button class="btn danger" data-act="logout">Delete all data</button>`}
A.exportData=()=>{const b=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='roblink-data.json';a.click();URL.revokeObjectURL(a.href)};
const PLUS=[['🎨','Custom themes & accent','Sunset, Aurora, Sakura & Neon gradient themes plus any accent colour.'],['🌈','Animated name','Your name shimmers everywhere you chat.'],['🖼️','Animated avatar & banner','GIF avatar and a profile banner image.'],['😎','Emoji everywhere','Use custom emoji from any of your servers anywhere.'],['📎','Bigger uploads','100 MB uploads and 4,000-character messages.'],['🚀','2 server boosts','Unlock banners, more emoji and animated icons for servers.'],['🔊','Soundboard','Play sounds in voice channels.'],['💥','Super reactions','Reactions that burst across the screen.'],['📺','HD streaming','Unlock 1080p / 60fps stream quality.'],['💎','Plus badge','Show off your badge on your profile.']];
function secPlus(){const m=S.me;
  if(m.plus)return`<h2>Roblink Plus</h2><div class="hero"><h1>💎 You're a Plus member!</h1><p>Thanks for supporting Roblink. Since ${new Date(m.plusSince||now()).toLocaleDateString()}.</p><b>Boosts left: ${m.boostsLeft}</b></div><h3>Your perks</h3><div class="feat">${PLUS.map(f=>`<div class="card"><div style="font-size:26px">${f[0]}</div><b>${f[1]}</b><span class="sub">${f[2]}</span></div>`).join('')}</div><h3>Manage</h3><button class="btn danger" data-act="cancelPlus">Cancel Plus</button><p class="sub">Demo only – no real subscription exists.</p>`;
  return`<h2>Roblink Plus</h2><div class="hero"><h1>💎 Unlock the full Roblink</h1><p>Make Roblink yours with themes, animated profiles, emoji everywhere, boosts and more.</p><button class="btn" style="background:#fff;color:#5b21b6;font-weight:700" data-act="getPlus" data-a="monthly">Get Plus – £2.99/mo</button> <button class="btn" style="background:rgba(255,255,255,.2);color:#fff" data-act="getPlus" data-a="yearly">£24.99/yr (save 30%)</button></div><p class="sub">This is a front-end demo: clicking a button activates Plus instantly and <b>no payment is taken</b>.</p><div class="feat">${PLUS.map(f=>`<div class="card"><div style="font-size:26px">${f[0]}</div><b>${f[1]}</b><span class="sub">${f[2]}</span></div>`).join('')}</div>`}
A.getPlus=()=>{S.me.plus=true;S.me.plusSince=now();S.me.boostsLeft=2;save();applyTheme();refreshApp();renderSet();renderRail();toast('💎 Welcome to Roblink Plus!');tone([[523,.1],[659,.1],[784,.1],[1047,.3]],1);for(let i=0;i<22;i++){const p=document.createElement('div');p.className='burst';p.textContent=pick(['💎','✨','🎉','⭐']);p.style.cssText=`left:50%;top:40%;--dx:${rnd(-400,400)}px;--dy:${rnd(-250,250)}px;--r:${rnd(-180,180)}deg;z-index:900`;document.body.appendChild(p);setTimeout(()=>p.remove(),1250)}};
A.cancelPlus=()=>confirmBox('Cancel Roblink Plus?','You\'ll lose your Plus themes, boosts and perks.','Cancel Plus',()=>{Object.entries(S.me.boosted||{}).forEach(([sid,n])=>{const s=S.servers.find(x=>x.id===sid);if(s)s.boosts=Math.max(0,s.boosts-n)});S.me.plus=false;S.me.boostsLeft=0;S.me.boosted={};save();applyTheme();refreshApp();renderSet();toast('Plus cancelled.')},1);
function secAppearance(){const s=S.set,p=S.me.plus;return`<h2>Appearance</h2><h3>Theme</h3><div class="themes">${THEMES.map(t=>`<div class="th ${s.theme===t[0]?'on':''}" data-act="setTheme" data-a="${t[0]}"><i style="background:${t[2]}"></i>${t[1]}${t[3]&&!p?'<span class="lk">🔒</span>':''}</div>`).join('')}</div>
  <h3>Accent colour</h3>${swatches('set.accent',s.accent)}<br><label class="lbl">Custom colour ${p?'':'💎 Plus'}</label><input type="color" data-bind="set.accent" data-plus="1" value="${s.accent}" style="width:60px;height:36px;border:0;background:none">
  ${selb('Message display','set.density',s.density,[['cozy','Cozy'],['compact','Compact']])}<label class="lbl">Chat font size: ${s.font}px</label><input type="range" min="12" max="22" step="1" data-bind="set.font" value="${s.font}" style="width:100%">
  ${tog('set.reduceMotion','Reduce motion','Turn off animations and transitions.',s.reduceMotion)}${tog('set.autoplayGif','Autoplay GIFs','',s.autoplayGif)}`}
A.setTheme=el=>{const t=THEMES.find(x=>x[0]===el.dataset.a);if(t[3]&&!S.me.plus){toast('That theme is a Roblink Plus perk 💎','err');return}S.set.theme=t[0];save();applyTheme();renderSet()};
function secNotifs(){const s=S.set;return`<h2>Notifications</h2>${tog('set.sounds','Enable notification sounds','Play a chime for new messages.',s.sounds)}${tog('set.mentionsOnly','Only sound for @mentions & DMs','',s.mentionsOnly)}${tog('set.desktop','Desktop notifications','Show a system notification for mentions.',s.desktop)}<h3>Test</h3><button class="btn" data-act="testSound">🔔 Play sound</button>`}
A.testSound=()=>tone([[880,.08],[1175,.12]],1);
function secVoice(){const s=S.set;return`<h2>Voice &amp; Video</h2><label class="lbl">Microphone volume: ${s.mic}%</label><input type="range" min="0" max="100" data-bind="set.mic" value="${s.mic}" style="width:100%"><label class="lbl">Speaker volume: ${s.spk}%</label><input type="range" min="0" max="100" data-bind="set.spk" value="${s.spk}" style="width:100%">${tog('set.noiseSup','Noise suppression','Filter background noise from your mic.',s.noiseSup)}${tog('set.hd','HD streaming (1080p / 60fps)','Higher quality screen sharing.',s.hd,0,1)}<h3>Camera</h3><button class="btn" data-act="camTest">📷 Test camera</button>`}
function secKeys(){return`<h2>Keybinds</h2><div class="card">${[['Ctrl / ⌘ + K','Quick switcher'],['Alt + ↑ / ↓','Previous / next channel'],['↑ (empty box)','Edit your last message'],['Enter','Send message'],['Shift + Enter','New line'],['Tab','Complete slash command'],['Esc','Close menus, modals and settings']].map(([k,d])=>`<div class="row"><span>${d}</span><b style="background:var(--bg1);padding:2px 8px;border-radius:4px;color:var(--text)">${k}</b></div>`).join('')}</div>`}
function secAdvanced(){return`<h2>Advanced</h2>${tog('set.dev','Developer mode','Adds “Copy ID” to right-click menus.',S.set.dev)}<h3>About</h3><p class="sub">Roblink demo build. All data lives only in this browser's local storage – there is no server, so other real people can't join yet.</p>`}

/* ----- server sections ----- */
const lvlPerks=['No perks yet','Level 1: animated server icon, +50 emoji slots','Level 2: server banner, +100 emoji slots','Level 3: max perks, +150 emoji slots'];
function secOverview(s){const can=perm(s,'me','MANAGE_SERVER'),d=!can;return`<h2>Server Overview</h2>${can?'':lock(s,'MANAGE_SERVER')}<div style="display:flex;gap:16px;align-items:center"><div class="srv" style="width:80px;height:80px;font-size:34px;background:${s.color}">${s.iconImg?`<img src="${s.iconImg}">`:esc(s.icon)}</div><div><label class="btn primary ${d?'':''}">Upload icon<input type="file" id="sIcon" accept="image/*" hidden ${d?'disabled':''}></label> <button class="btn" data-act="rmSrvIcon" ${d?'disabled':''}>Remove</button><p class="sub">GIF icons need Boost Level 1.</p></div></div>
  ${fld('Server name','srv.name',s.name,{max:40,dis:d})}${fld('Icon text / emoji','srv.icon',s.icon,{max:2,dis:d})}${fld('Description','srv.desc',s.desc,{area:1,max:150,dis:d})}<label class="lbl">Icon colour</label>${swatches('srv.color',s.color,d)}
  <h3>Banner (Boost Level 2)</h3>${boostLevel(s)>=2?`<input type="color" data-bind="srv.bannerColor" value="${s.bannerColor}" ${d?'disabled':''}> <label class="btn">Upload banner<input type="file" id="sBanner" accept="image/*" hidden ${d?'disabled':''}></label> <button class="btn" data-act="rmSrvBanner">Remove</button>`:`<p class="sub">🔒 This server needs ${7-s.boosts} more boost${7-s.boosts===1?'':'s'} to unlock banners.</p>`}`}
A.rmSrvIcon=()=>{const s=srvOf();s.iconImg=null;save();renderRail();renderSet()};A.rmSrvBanner=()=>{const s=srvOf();s.bannerImg=null;save();renderSide();renderSet()};
function secRoles(s){const can=perm(s,'me','MANAGE_ROLES');const sel=V.set.role||(s.roles[0]&&s.roles[0].id)||'everyone';const idx=s.roles.findIndex(r=>r.id===sel),isEv=sel==='everyone'||idx<0,r=isEv?null:s.roles[idx];const editable=can&&(isEv||idx>rank(s,'me'));
  const po=isEv?s.everyone:r.perms,base=isEv?'srv.everyone':`srv.roles.${idx}.perms`;const owner=s.owner==='me';
  return`<h2>Roles</h2>${can?'<p class="sub">Roles are ordered by power: roles higher in the list outrank those below. Members get the permissions of all their roles.</p>':lock(s,'MANAGE_ROLES')}<div class="rl"><div class="lst">${can?'<button class="btn primary sm" style="width:100%;margin-bottom:8px" data-act="roleNew">＋ Create Role</button>':''}${s.roles.map(x=>`<div class="ri ${x.id===sel?'on':''}" data-act="roleSel" data-a="${x.id}"><i style="background:${x.color}"></i>${esc(x.name)}</div>`).join('')}<div class="ri ${isEv?'on':''}" data-act="roleSel" data-a="everyone"><i style="background:#80848e"></i>@everyone</div></div><div class="ed">
  ${isEv?'<h3 style="margin-top:0">@everyone</h3><p class="sub">Default permissions for every member.</p>':`<h3 style="margin-top:0">Edit role</h3>${fld('Role name',`srv.roles.${idx}.name`,r.name,{max:30,dis:!editable})}<label class="lbl">Role colour</label><div style="display:flex;gap:10px;align-items:center"><input type="color" data-bind="srv.roles.${idx}.color" value="${r.color}" ${editable?'':'disabled'} style="width:48px;height:32px;border:0;background:none">${COLORS.map(c=>`<div class="sw ${c===r.color?'on':''}" style="background:${c};width:24px;height:24px" data-act="${editable?'setColor':'noop'}" data-a="srv.roles.${idx}.color" data-b="${c}"></div>`).join('')}</div>${tog(`srv.roles.${idx}.hoist`,'Display separately in member list','',r.hoist,!editable)}<div style="margin:10px 0"><button class="btn sm" data-act="roleUp" data-a="${idx}" ${editable&&idx>rank(s,'me')+1?'':'disabled'}>▲ Move up</button> <button class="btn sm" data-act="roleDown" data-a="${idx}" ${editable&&idx<s.roles.length-1?'':'disabled'}>▼ Move down</button> <button class="btn sm danger" data-act="roleDel" data-a="${idx}" ${editable?'':'disabled'}>Delete</button></div>`}
  <h3>Permissions</h3>${Object.entries(PERMS).map(([k,[n,d]])=>tog(`${base}.${k}`,n,d,po[k],!editable||(!owner&&!perm(s,'me',k)))).join('')}</div></div>`}
A.roleSel=el=>{V.set.role=el.dataset.a;renderSet()};
A.roleNew=()=>{const s=srvOf();const r=mkRole('new role',pick(COLORS),{});const at=Math.max(0,rank(s,'me')+1);s.roles.splice(Math.min(at,s.roles.length),0,r);V.set.role=r.id;audit(s,'created a role');save();renderSet()};
A.roleUp=el=>{const s=srvOf(),i=+el.dataset.a;[s.roles[i-1],s.roles[i]]=[s.roles[i],s.roles[i-1]];save();renderSet();renderMembers()};
A.roleDown=el=>{const s=srvOf(),i=+el.dataset.a;[s.roles[i+1],s.roles[i]]=[s.roles[i],s.roles[i+1]];save();renderSet();renderMembers()};
A.roleDel=el=>{const s=srvOf(),i=+el.dataset.a,r=s.roles[i];confirmBox('Delete role',`Delete <b>${esc(r.name)}</b>? Members will lose it.`,'Delete',()=>{Object.values(s.members).forEach(m=>m.roles=m.roles.filter(x=>x!==r.id));s.roles.splice(i,1);V.set.role=null;audit(s,`deleted role ${r.name}`);save();renderSet();refreshApp()},1)};
function secEmoji(s){const can=perm(s,'me','MANAGE_EMOJI'),lim=50+boostLevel(s)*50;return`<h2>Emoji</h2>${can?'':lock(s,'MANAGE_EMOJI')}<p class="sub">${s.emojis.length} / ${lim} slots used. Upload a small image (it will be resized to 64×64). Use it in chat by typing <code>:name:</code>.</p>${can?`<label class="btn primary">Upload emoji<input type="file" id="emFile" accept="image/*" hidden></label>`:''}<table class="tbl" style="margin-top:12px"><tr><th>Emoji</th><th>Name</th><th></th></tr>${s.emojis.map((e,i)=>`<tr><td><img class="cemoji" style="width:32px;height:32px" src="${e.data}"></td><td>:${esc(e.name)}:</td><td>${can?`<button class="btn sm danger" data-act="emDel" data-a="${i}">Delete</button>`:''}</td></tr>`).join('')||'<tr><td colspan=3 class="sub">No emoji yet.</td></tr>'}</table>`}
A.emDel=el=>{const s=srvOf();s.emojis.splice(+el.dataset.a,1);audit(s,'removed an emoji');save();renderSet();renderMsgs()};
function secBoost(s){const lvl=boostLevel(s),nxt=[2,7,14][lvl],pct=lvl>=3?100:Math.round(s.boosts/nxt*100),mine=(S.me.boosted||{})[s.id]||0;
  return`<h2>Server Boost Status</h2><div class="boost"><h3 style="margin:0;color:#fff">🚀 Level ${lvl}</h3><b>${s.boosts} boost${s.boosts===1?'':'s'}</b>${lvl<3?` — ${nxt-s.boosts} more for Level ${lvl+1}`:' — max level!'}<div class="bar"><i style="width:${pct}%"></i></div></div>
  ${[1,2,3].map(l=>`<div class="row"><span>${lvl>=l?'✅':'🔒'} ${lvlPerks[l]}</span><span class="sub">${[2,7,14][l-1]} boosts</span></div>`).join('')}
  <h3>Your boosts</h3>${S.me.plus?`<p>You have <b>${S.me.boostsLeft}</b> boost${S.me.boostsLeft===1?'':'s'} left. You've applied <b>${mine}</b> here.</p><button class="btn primary" data-act="boostIt" ${S.me.boostsLeft<1?'disabled':''}>🚀 Boost this server</button> <button class="btn" data-act="unboost" ${mine?'':'disabled'}>Remove my boost</button>`:`<p class="sub">Roblink Plus includes 2 free boosts.</p><button class="btn primary" data-act="openSet" data-a="plus">Get Roblink Plus</button>`}`}
A.boostIt=()=>{const s=srvOf();if(S.me.boostsLeft<1)return;S.me.boostsLeft--;S.me.boosted[s.id]=(S.me.boosted[s.id]||0)+1;s.boosts++;audit(s,'boosted the server');save();renderSet();refreshApp();toast('🚀 Server boosted!')};
A.unboost=()=>{const s=srvOf();if(!(S.me.boosted[s.id]>0))return;S.me.boosted[s.id]--;S.me.boostsLeft++;s.boosts--;save();renderSet();refreshApp()};
function secSafety(s){const d=!perm(s,'me','MANAGE_SERVER');return`<h2>Safety Setup</h2>${d?lock(s,'MANAGE_SERVER'):''}${selb('Verification level','srv.verification',s.verification,[['none','None'],['low','Low – verified email'],['medium','Medium – registered 5+ minutes'],['high','High – member 10+ minutes']],d)}${selb('Explicit media filter','srv.filter',s.filter,[['off','Don\'t scan'],['members','Scan members without roles'],['all','Scan all members']],d)}<h3>AutoMod</h3>${tog('srv.automod.on','Enable word filter','Requires <b>ModBot</b> to be in the server. Matching messages are deleted automatically.',s.automod.on,d)}<label class="lbl">Blocked words (comma separated)</label><textarea class="input" rows="2" data-fn="words" ${d?'disabled':''}>${esc(s.automod.words.join(', '))}</textarea>${s.bots.includes('modbot')?'':'<p class="sub" style="color:var(--yellow)">⚠️ ModBot isn\'t installed. Add it under Bots &amp; Integrations.</p>'}`}
function secChannels(s){const can=perm(s,'me','MANAGE_CHANNELS');return`<h2>Channels</h2>${can?'':lock(s,'MANAGE_CHANNELS')}${can?'<button class="btn primary sm" data-act="newCh">＋ Create channel</button> <button class="btn sm" data-act="newCat">＋ Create category</button>':''}<table class="tbl" style="margin-top:12px"><tr><th>Name</th><th>Type</th><th>Category</th><th></th></tr>${s.channels.map((c,i)=>`<tr><td>${c.type==='voice'?'🔊':'#'} ${esc(c.name)}</td><td>${c.type}</td><td>${esc((s.categories.find(k=>k.id===c.cat)||{}).name||'—')}</td><td>${can?`<button class="ib" data-act="chUp" data-a="${i}">▲</button><button class="ib" data-act="chDown" data-a="${i}">▼</button><button class="ib" data-act="editCh" data-a="${c.id}">✏️</button>`:''}</td></tr>`).join('')}</table>`}
A.newCat=()=>newCatModal(srvOf());
A.chUp=el=>{const s=srvOf(),i=+el.dataset.a;if(i>0){[s.channels[i-1],s.channels[i]]=[s.channels[i],s.channels[i-1]];save();renderSet();renderSide()}};
A.chDown=el=>{const s=srvOf(),i=+el.dataset.a;if(i<s.channels.length-1){[s.channels[i+1],s.channels[i]]=[s.channels[i],s.channels[i+1]];save();renderSet();renderSide()}};
function secMembers(s){const q=(V.set.q||'').toLowerCase();const ids=Object.keys(s.members).filter(i=>getUser(i)&&(!q||getUser(i).name.toLowerCase().includes(q)));const canR=perm(s,'me','MANAGE_ROLES');
  return`<h2>Members</h2><input class="input" placeholder="Search members" data-fn="memq" value="${esc(V.set.q||'')}" id="mq"><table class="tbl" style="margin-top:12px"><tr><th>Member</th><th>Roles</th><th></th></tr>${ids.map(i=>{const u=getUser(i),m=s.members[i],mg=i!=='me'&&canManage(s,i);const chips=m.roles.map(rid=>s.roles.find(r=>r.id===rid)).filter(Boolean);const ridx=r=>s.roles.indexOf(r);return`<tr><td><div style="display:flex;gap:8px;align-items:center">${av(u,28,true)}<span>${esc(dispName(u,s))}${i===s.owner?' 👑':''}${u.bot?' <span class="badge">BOT</span>':''}</span></div></td><td>${chips.map(r=>`<span class="role"><i style="background:${r.color}"></i>${esc(r.name)}${canR&&ridx(r)>rank(s,'me')&&(mg||i==='me'&&s.owner==='me')?`<b data-act="rmRole" data-a="${i}" data-b="${r.id}">×</b>`:''}</span>`).join('')}${canR&&(mg||s.owner==='me')?`<span class="role" style="cursor:pointer" data-act="addRole" data-a="${i}">＋</span>`:''}${m.timeout>now()?'<span class="role">⏳ timed out</span>':''}</td><td style="white-space:nowrap">${mg?`${perm(s,'me','TIMEOUT')?`<button class="ib" title="Timeout" data-act="mTimeout" data-a="${i}">⏳</button>`:''}${perm(s,'me','KICK')?`<button class="ib" title="Kick" data-act="mKick" data-a="${i}">👢</button>`:''}${perm(s,'me','BAN')?`<button class="ib" title="Ban" data-act="mBan" data-a="${i}">🔨</button>`:''}`:''}</td></tr>`}).join('')}</table>`}
A.rmRole=el=>{const s=srvOf(),m=s.members[el.dataset.a];m.roles=m.roles.filter(r=>r!==el.dataset.b);audit(s,`removed a role from ${getUser(el.dataset.a).name}`);save();renderSet();refreshApp()};
A.addRole=(el,e)=>{const s=srvOf(),id=el.dataset.a,m=s.members[id],r=el.getBoundingClientRect();const opts=s.roles.filter(x=>!m.roles.includes(x.id)&&(s.owner==='me'||s.roles.indexOf(x)>rank(s,'me')));ctxMenu(r.left,r.bottom,opts.length?opts.map(x=>({l:`<span style="color:${x.color}">●</span> ${esc(x.name)}`,fn:()=>{m.roles.push(x.id);audit(s,`gave ${x.name} to ${getUser(id).name}`);save();renderSet();refreshApp()}})):[{l:'No roles available'}])};
A.mTimeout=el=>timeoutModal(srvOf(),el.dataset.a);A.mKick=el=>modAct('kick',srvOf(),el.dataset.a);A.mBan=el=>modAct('ban',srvOf(),el.dataset.a);
function secBots(s){const can=perm(s,'me','MANAGE_SERVER');return`<h2>Bots &amp; Integrations</h2>${can?'':lock(s,'MANAGE_SERVER')}<p class="sub">Bots respond to slash commands in this server. Try <code>/help</code> in chat.</p>${Object.entries(BOTS).map(([id,b])=>{const on=s.bots.includes(id);return`<div class="card" style="display:flex;gap:12px;align-items:center">${av(S.users[id],44)}<div style="flex:1"><b style="color:var(--text)">${b.name}</b> <span class="badge">BOT</span><div class="sub">${b.desc}</div><div class="sub" style="font-size:12px">${Object.keys(b.cmds).map(c=>'/'+c).join('  ')}</div></div>${can?`<button class="btn sm ${on?'danger':'green'}" data-act="botToggle" data-a="${id}">${on?'Remove':'Add to server'}</button>`:`<span class="sub">${on?'Installed':''}</span>`}</div>`}).join('')}`}
A.botToggle=el=>{const s=srvOf(),id=el.dataset.a;if(s.bots.includes(id)){s.bots=s.bots.filter(b=>b!==id);delete s.members[id];audit(s,`removed ${BOTS[id].name}`)}else{s.bots.push(id);let br=s.roles.find(r=>r.name==='Bots');if(!br){br=mkRole('Bots','#a78bfa',{},true);s.roles.push(br)}s.members[id]={roles:[br.id],nick:'',joined:now(),timeout:0};audit(s,`added ${BOTS[id].name}`);const g=s.channels.find(c=>c.name==='general')||s.channels.find(c=>c.type==='text');S.messages[g.id].push({id:uid(),a:id,t:`👋 Hi! **${BOTS[id].name}** has joined. Try ${Object.values(BOTS[id].cmds).map(x=>'`'+x.split(' –')[0]+'`').join(', ')}`,ts:now(),rx:{}})}save();renderSet();refreshApp()};
function secInvites(s){const can=perm(s,'me','INVITE');return`<h2>Invites</h2>${can?'':lock(s,'INVITE')}<div class="card"><div class="sub">Main invite code</div><div style="display:flex;gap:8px;margin-top:6px"><input class="input" readonly value="${s.invite}"><button class="btn primary" data-act="copy" data-a="${s.invite}">Copy</button></div></div>${can?'<button class="btn primary sm" data-act="newInvite">＋ Create invite</button> <button class="btn sm" data-act="invPeople">Invite friends</button>':''}<table class="tbl" style="margin-top:12px"><tr><th>Code</th><th>Inviter</th><th>Uses</th><th></th></tr>${s.invites.map((v,i)=>`<tr><td><code>${v.code}</code></td><td>${esc(getUser(v.by)?getUser(v.by).name:'?')}</td><td>${v.uses}${v.max?' / '+v.max:''}</td><td>${can?`<button class="btn sm danger" data-act="invDel" data-a="${i}">Revoke</button>`:''}</td></tr>`).join('')||'<tr><td colspan=4 class="sub">No custom invites yet.</td></tr>'}</table>`}
A.newInvite=()=>{const s=srvOf();s.invites.push({code:uid().slice(0,7),by:'me',uses:0,max:0,ts:now()});audit(s,'created an invite');save();renderSet()};
A.invDel=el=>{const s=srvOf();s.invites.splice(+el.dataset.a,1);save();renderSet()};A.invPeople=()=>inviteModal(srvOf());
function secBans(s){const can=perm(s,'me','BAN');return`<h2>Bans</h2>${can?'':lock(s,'BAN')}<table class="tbl"><tr><th>User</th><th>Reason</th><th>Date</th><th></th></tr>${s.bans.map((b,i)=>`<tr><td>${esc(getUser(b.id)?getUser(b.id).name:b.id)}</td><td>${esc(b.reason||'—')}</td><td>${new Date(b.ts).toLocaleDateString()}</td><td>${can?`<button class="btn sm" data-act="unban" data-a="${i}">Unban</button>`:''}</td></tr>`).join('')||'<tr><td colspan=4 class="sub">No one is banned. 🎉</td></tr>'}</table>`}
A.unban=el=>{const s=srvOf(),b=s.bans.splice(+el.dataset.a,1)[0];audit(s,`unbanned ${getUser(b.id)?getUser(b.id).name:b.id}`);save();renderSet()};
function secAudit(s){return`<h2>Audit Log</h2>${s.audit.length?s.audit.map(a=>`<div class="row"><span><b style="color:var(--text)">${esc(a.who)}</b> ${esc(a.t)}</span><span class="sub">${fmtTime(a.ts)}</span></div>`).join(''):'<p class="sub">Nothing here yet.</p>'}`}
function secDelete(s){if(s.owner!=='me')return`<h2>Leave Server</h2><p class="sub">You are not the owner of this server.</p><button class="btn danger" data-act="leaveFromSet">Leave ${esc(s.name)}</button>`;return`<h2>Delete Server</h2><div class="card" style="border-left:4px solid var(--red)">Deleting <b>${esc(s.name)}</b> is permanent and removes all channels and messages.</div><label class="lbl">Type the server name to confirm</label><input class="input" id="delc" placeholder="${esc(s.name)}"><br><br><button class="btn danger" data-act="delServer">Delete Server</button>`}
A.leaveFromSet=()=>{const s=srvOf();A.closeSet();leaveServer(s)};
A.delServer=()=>{const s=srvOf();if($('#delc').value!==s.name)return toast('Server name does not match.','err');s.channels.forEach(c=>delete S.messages[c.id]);Object.entries(S.me.boosted||{}).forEach(([k,n])=>{if(k===s.id)S.me.boostsLeft+=n});S.servers=S.servers.filter(x=>x!==s);if(V.voice&&V.voice.sid===s.id)V.voice=null;A.closeSet();go('home');toast('Server deleted.')};

/* ---------- global events ---------- */
document.addEventListener('click',e=>{
  const pk=$('.picker');if(pk&&!e.target.closest('.picker')&&!e.target.closest('[data-act=emojiPick],[data-act=reactPick]'))pk.remove();
  if(!e.target.closest('.ctx'))closeCtx();
  const sg=e.target.closest('#suggest [data-cmd]');if(sg){const i=$('#input');i.value=sg.dataset.cmd+' ';i.focus();$('#suggest').style.display='none';return}
  const el=e.target.closest('[data-act]');if(!el)return;const f=A[el.dataset.act];if(f){if(el.tagName==='A')e.preventDefault();f(el,e)}});
document.addEventListener('contextmenu',e=>{const el=e.target.closest('[data-ctx]');if(!el||!S)return;e.preventDefault();ctxFor(el,e.clientX,e.clientY)});
document.addEventListener('input',e=>{const t=e.target;
  if(t.dataset.bind){let path=t.dataset.bind,val=t.type==='checkbox'?t.checked:(t.type==='range'||t.type==='number')?Number(t.value):t.value;
    if(t.dataset.plus&&!S.me.plus){if(t.type==='checkbox')t.checked=false;else if(t.type==='color'){t.value=S.set.accent}toast('That\'s a Roblink Plus perk 💎','err');return}
    if(path==='me.username')val=val.toLowerCase().replace(/[^a-z0-9_.]/g,'');if((path==='me.name'||path==='srv.name'||path.endsWith('.name'))&&!val.trim()&&t.type==='text')return;
    setPath(path,val);save();applyTheme();refreshApp();
    if(t.type==='checkbox'||t.tagName==='SELECT')renderSet();else{updatePreview();if(t.type==='range'){const l=t.previousElementSibling;if(l&&l.classList.contains('lbl'))l.textContent=l.textContent.replace(/:.*$/,': '+val+(path==='set.font'?'px':'%'))}}}
  else if(t.dataset.fn==='words'){const s=srvOf();s.automod.words=t.value.split(',').map(x=>x.trim()).filter(Boolean);save()}
  else if(t.dataset.fn==='memq'){V.set.q=t.value;const pos=t.selectionStart;renderSet();const n=$('#mq');n.focus();n.setSelectionRange(pos,pos)}
  else if(t.id==='input'){autosize(t);V.drafts[convKey()]=t.value;const lim=S.me.plus?4000:2000;$('#cnt').textContent=t.value.length>lim*.85?`${t.value.length}/${lim}`:'';suggest(t.value)}});
document.addEventListener('change',e=>{const t=e.target,f=t.files&&t.files[0];
  if(t.id==='file'&&f){readImage(f,1000,d=>{V.att=d;renderAtt()});t.value=''}
  else if(t.id==='avFile'&&f){readImage(f,256,(d,gif)=>{if(gif&&!S.me.plus)return toast('Animated avatars require Roblink Plus 💎','err');S.me.avatarImg=d;save();updatePreview();refreshApp();renderSet()});t.value=''}
  else if(t.id==='bnFile'&&f){if(!S.me.plus){toast('Banner images require Roblink Plus 💎','err');t.value='';return}readImage(f,900,d=>{S.me.bannerImg=d;save();updatePreview();renderSet()});t.value=''}
  else if(t.id==='sIcon'&&f){const s=srvOf();readImage(f,128,(d,gif)=>{if(gif&&boostLevel(s)<1)return toast('Animated icons need Boost Level 1.','err');s.iconImg=d;audit(s,'changed the server icon');save();renderRail();renderSet()});t.value=''}
  else if(t.id==='sBanner'&&f){const s=srvOf();readImage(f,900,d=>{s.bannerImg=d;save();renderSide();renderSet()});t.value=''}
  else if(t.id==='emFile'&&f){const s=srvOf(),lim=50+boostLevel(s)*50;if(s.emojis.length>=lim){toast('No emoji slots left – boost the server for more!','err');t.value='';return}readImage(f,64,d=>{let n=f.name.replace(/\.[^.]+$/,'').toLowerCase().replace(/[^a-z0-9_]/g,'_').slice(0,20);if(n.length<2)n='emoji'+rnd(10,99);while(s.emojis.some(x=>x.name===n))n+=rnd(0,9);s.emojis.push({id:uid(),name:n,data:d});audit(s,`added emoji :${n}:`);save();renderSet()},1);t.value=''}
  else if(t.dataset.bind==='me.username'||t.dataset.bind==='me.name')renderSet()});
document.addEventListener('paste',e=>{if(e.target.id!=='input')return;const f=[...(e.clipboardData.files||[])].find(x=>x.type.startsWith('image/'));if(f){e.preventDefault();readImage(f,1000,d=>{V.att=d;renderAtt()})}});
document.addEventListener('keydown',e=>{
  if(!S)return;const t=e.target;
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();quickSwitch();return}
  if(e.key==='Escape'){if($('.picker')){$('.picker').remove();return}if($('.ctx')){closeCtx();return}if($('.lightbox')){$('.lightbox').remove();return}if($('#modal')){closeModal();return}if(V.edit){A.cancelEdit();return}if(V.set){A.closeSet();return}if(V.reply){A.cancelReply();return}}
  if(t.id==='editbox'){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();A.saveEdit()}return}
  if(t.id==='search'&&e.key==='Enter'){doSearch(t.value);t.value='';return}
  if(t.id==='input'){
    if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();A.send();return}
    if(e.key==='Tab'&&$('#suggest')&&$('#suggest').style.display!=='none'){e.preventDefault();const f=$('#suggest [data-cmd]');if(f){t.value=f.dataset.cmd+' ';$('#suggest').style.display='none'}return}
    if(e.key==='ArrowUp'&&!t.value){const l=(S.messages[convKey()]||[]).filter(m=>m.a==='me'&&!m.sys);const m=l[l.length-1];if(m){e.preventDefault();V.edit=m.id;renderMsgs()}}}
  if(e.altKey&&(e.key==='ArrowUp'||e.key==='ArrowDown')){const s=curServer();if(!s)return;const l=s.channels.filter(c=>c.type==='text'),i=l.findIndex(c=>c.id===V.channel),n=l[(i+(e.key==='ArrowDown'?1:-1)+l.length)%l.length];if(n){e.preventDefault();go(s.id,n.id)}}});
function suggest(v){const box=$('#suggest');if(!box)return;if(v[0]!=='/'||v.includes(' ')){box.style.display='none';return}const s=curServer(),d=curDm();
  const list=[['/help','Show available commands'],['/me','Action message'],['/shrug','¯\\_(ツ)_/¯'],['/spoiler','Hide text'],['/nick','Set your nickname']];
  (s?s.bots:(d&&S.users[d.user].bot?[d.user]:[])).forEach(b=>Object.values(BOTS[b].cmds).forEach(x=>{const[c,ds]=x.split(' – ');list.push([c.split(' ')[0],`${BOTS[b].name}: ${ds}`])}));
  const m=list.filter(x=>x[0].startsWith(v.toLowerCase())).slice(0,7);box.style.display=m.length?'block':'none';box.innerHTML=m.map(x=>`<div data-cmd="${esc(x[0])}"><b>${esc(x[0])}</b><span>${esc(x[1])}</span></div>`).join('')}
document.addEventListener('dragover',e=>e.preventDefault());
document.addEventListener('drop',e=>{e.preventDefault();const f=e.dataTransfer.files&&e.dataTransfer.files[0];if(f&&$('#input'))readImage(f,1000,d=>{V.att=d;renderAtt()})});
window.addEventListener('beforeunload',()=>{if(S)try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}});

/* ---------- boot ---------- */
function showAuth(){let color=COLORS[0];const b=$('#boot');b.innerHTML=`<div class="auth"><div class="lg">${LOGO}</div><h1>Welcome to Roblink</h1><p class="sub">Chat, hang out and build communities.</p><label class="lbl">Username *</label><input class="input" id="au" maxlength="20" placeholder="e.g. pineapplekid"><label class="lbl">Display name</label><input class="input" id="ad" maxlength="32" placeholder="Shown on your messages"><label class="lbl">Avatar colour</label><div class="swatches" id="asw">${COLORS.map((c,i)=>`<div class="sw ${i?'':'on'}" style="background:${c}" data-c="${c}"></div>`).join('')}</div><br><button class="btn primary" style="width:100%;padding:12px" id="ago">Continue</button><p class="sub" style="font-size:12px">Demo build – everything is stored locally in your browser.</p></div>`;
  $('#asw').onclick=e=>{const c=e.target.closest('[data-c]');if(!c)return;color=c.dataset.c;$$('#asw .sw').forEach(x=>x.classList.toggle('on',x===c))};
  const go_=()=>{const u=$('#au').value.trim().toLowerCase().replace(/[^a-z0-9_.]/g,'');if(u.length<2)return toast('Pick a username (2+ letters/numbers).','err');if(Object.keys(NPCS.reduce((a,n)=>(a[n[0]]=1,a),{})).includes(u)||u in BOTS)return toast('That username is taken.','err');newState({id:'me',username:u,name:$('#ad').value.trim()||u,color,about:'',pronouns:'',status:'online',customStatus:'',plus:false,boostsLeft:0,boosted:{},created:now(),bannerColor:color});start()};
  $('#ago').onclick=go_;$('#au').onkeydown=e=>{if(e.key==='Enter')go_()}}
function start(){
  $('#boot').remove();S.me.boosted=S.me.boosted||{};S.set={...DEF_SET,...S.set};S.unread=S.unread||{};S.last=S.last||{};applyTheme();
  const ls=S.servers.find(s=>s.id===S.last.server);if(ls)go(ls.id,S.last.channel);else go('home');
  (function loop(){setTimeout(()=>{try{npcTick()}catch(e){}loop()},rnd(14,26)*1000)})();
  setInterval(()=>{$$('[data-vu]').forEach(el=>el.classList.toggle('speaking',Math.random()<.3&&(el.dataset.vu!=='me'||!V.muted)))},1400);
  setTimeout(()=>{if(S.pending.some(p=>p.dir==='in')&&V.server==='home'&&!V.dm){/* hint */}},500)}
if(!S||!S.me)showAuth();else start();
